export const day=(offset=0)=>new Date(Date.now()+offset*86400000).toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'});
const text=z.string().max(20000), short=z.string().trim().min(1).max(200), num=z.number().finite().min(0).max(1000000), date=z.string().regex(/^\d{4}-\d{2}-\d{2}$/).refine(s=>Number.isFinite(Date.parse(s+'T12:00:00Z'))&&new Date(s+'T12:00:00Z').toISOString().slice(0,10)===s), timestamp=z.string().refine(s=>Number.isFinite(Date.parse(s)));
