export const schemas={
 tasks:z.object({...base,title:short,project:text.default('日常'),priority:z.enum(['high','normal','low']).default('normal'),status:z.enum(['todo','doing','done']).default('todo'),due:date,note:text.default(''),completed:z.string().default('')}),
 habits:z.object({...base,title:short,type:z.enum(['boolean','count','number']),target:z.number().positive().max(100000),unit:short,checks:z.record(date,num).default({})}),
 health:z.object({...base,date,steps:num.default(0),resting:num.default(0),active:num.default(0),intake:num.default(0),exercise:num.max(1440).default(0),weight:num.max(600).default(0),water:num.max(30000).default(0),mood:z.number().int().min(1).max(5).default(3),note:text.default('')}),
 meals:z.object({...base,date,title:short,meal:z.enum(['早餐','午餐','晚餐','加餐']),calories:num.max(20000),note:text.default('')}),
 sleep:z.object({...base,date,start:timestamp,end:timestamp,score:num.max(100),deep:num.max(1440),light:num.max(1440),rem:num.max(1440),awake:num.max(1440),awakenings:num.max(100),heartRate:num.max(250),note:text.default('')}).refine(s=>Date.parse(s.end)>Date.parse(s.start)&&Date.parse(s.end)-Date.parse(s.start)<=48*3600000,{message:'起床时间必须晚于入睡时间，且在 48 小时内'}).refine(s=>Math.abs((s.deep+s.light+s.rem+s.awake)*60000-(Date.parse(s.end)-Date.parse(s.start)))<60001,{message:'睡眠阶段合计应与起止时长一致（允许 1 分钟误差）'}),
 library:z.object({...base,title:short,kind:z.enum(['番剧','Galgame','游戏','书籍','电影']),creator:text.default(''),status:z.enum(['wish','playing','done','paused']),progress:num,total:z.number().positive().max(100000),rating:num.max(10).default(0),tags:text.default(''),note:text.default(''),cover:z.string().regex(/^\/(assets|uploads)\/[\w.-]+$/).default('/assets/flower-03.webp'),favorite:z.boolean().default(false),route:text.default(''),character:text.default(''),quote:text.default('')}).refine(x=>x.progress<=x.total,{message:'进度不能超过总进度'}),
 notes:z.object({...base,date,title:short,content:text}),
 posts:z.object({...base,title:short,slug:z.string().regex(/^[a-z0-9][a-z0-9-]{0,100}$/),excerpt:z.string().max(500),content:z.string().max(200000),category:short,tags:text.default(''),cover:z.string().regex(/^$|^\/(assets|uploads)\/[\w.-]+$/).default(''),status:z.enum(['draft','published','private','scheduled']),publishAt:timestamp,featured:z.boolean().default(false),type:z.union([z.literal(1),z.literal(2),z.literal(3)]).default(1),origin_url:z.string().max(2000).refine(s=>!s||/^https?:\/\//i.test(s)).nullable().default(''),order:z.number().int().min(1).max(999).nullable().default(null)}),
};
export const profileSchema=z.object({name:short,tagline:z.string().max(200),bio:z.string().max(2000),interests:z.string().max(500),favoriteAnime:z.string().max(300),favoriteGames:z.string().max(300),season:z.string().max(100),accent:z.enum(['sage','rose','blue']),scene:z.enum(['cafe','flower','may','atri','charlotte','wada']),wallpaper:z.enum(['landscape-fields','landscape-room','landscape-study','landscape-dawn','landscape-fantasy','landscape-journey','landscape-orbit','landscape-eye','landscape-games','dimension-sunset','dimension-blue','dimension-gold','dimension-violet','dimension-pink']).default('dimension-blue'),blogWallpaper:z.enum(['landscape-fields','landscape-room','landscape-study','landscape-dawn','dimension-sunset','dimension-blue','dimension-gold','dimension-violet','dimension-pink']).default('dimension-sunset'),voice:z.string().regex(/^greeting-(0[0-9]|1[0-8])$/).default('greeting-00'),stepsGoal:z.number().min(1).max(100000),sleepGoal:z.number().min(1).max(24),waterGoal:z.number().min(1).max(20000)});
