export const defaultStory=()=>({round:1,points:0,lastClick:0,phase:'normal',unlocks:{},scene:0,lastLine:'',seen:[]});
const lines={negative:['稍微慢一点，我还没反应过来呢。','隐藏选项也不是这样连点出来的呀。','先去喝口水，再回来好不好？','今天的快进键暂时休息。'],early:['今天也见到你了，真好。','咖啡还温着，故事慢慢说。','存档已经准备好，今天想走哪条路线？','不用急着通关，日常回也很珍贵。','一小步，也值得记在今天的存档里。'],close:['你出现的时候，日常就多了一点亮色。','这段剧情，没有你可不行。','今天的好心情，要不要一起存档？','下一次见面，也留在日程里吧。'],second:['熟悉的开场，但这次知道你会来。','二周目也别快进，好台词值得再看。','咖啡续杯，故事也续一段。','这一次，把喜欢的日常再过一遍。']};
export function interact(story,now=Date.now()){
 const s=structuredClone(story); if(s.phase!=='normal')return s;
 const fast=now-s.lastClick<600;s.lastClick=now;s.points=Math.max(-100,Math.min(s.round===1?100:200,s.points+(fast?-50:10)));s.scene=(s.scene+1)%3;s.unlocks.hello??=now;if(s.points===-100)s.unlocks.cold??=now;
 if(s.round===1&&s.points===100){s.phase='transition';s.unlocks.second??=now;}
 if(s.round===2&&s.points===200){s.phase='epilogue';s.unlocks.after??=now;}
 const pool=lines[s.points<0?'negative':s.round===2?'second':s.points>=60?'close':'early'];const choices=pool.filter(x=>!s.seen.includes(x));s.lastLine=(choices.length?choices:pool.filter(x=>x!==s.lastLine))[Math.floor(Math.random()*(choices.length||pool.length-1))];s.seen=[...s.seen,s.lastLine].slice(-3);return s;
}
export function finishStory(story){const s=structuredClone(story);if(s.phase==='transition'){s.round=2;s.points=0;}else if(s.phase==='epilogue'){s.round=1;s.points=0;}s.phase='normal';return s;}
