 for(let i=6;i>=0;i--){add('health',[{date:day(-i),steps:4800+i*430,resting:1500,active:230+i*20,intake:0,exercise:20+i*3,weight:0,water:1200+i*100,mood:4,note:'示例记录'}]);const d=day(-i);add('sleep',[{date:d,start:day(-i-1)+'T23:30:00+08:00',end:d+'T07:30:00+08:00',score:82+i,deep:100+i*3,light:260-i*3,rem:100,awake:20,awakenings:2,heartRate:58,note:'示例睡眠记录'}]);}
 add('posts',[{title:'把生活，写成自己喜欢的样子',slug:'a-place-of-my-own',excerpt:'在效率之外，给喜欢的故事留一个位置。关于这个个人空间，以及那些值得被好好记住的日常。',content:'# 留一个属于自己的角落\n\n这是第一篇示例文章。你可以在写作间修改它，也可以从空白开始。\n\n## 日常，也值得被记录\n\n一杯刚好的咖啡，一段没舍得快进的剧情，一次终于完成的小任务。它们看起来普通，却构成了生活最具体的样子。\n\n> 不必把每一天过成高光时刻。平凡的章节，也有自己的光。\n\n## 从喜欢的事情出发\n\n这个空间把工作、生活和兴趣放在一起。认真做事，也认真休息。\n\n- 给正在追的故事留一张书签\n- 为下一次出发存好进度\n- 记下今天的小小收获\n\n## 慢慢更新\n\n关于技术、作品，以及生活里遇到的有趣瞬间，都会陆续写在这里。',category:'日常手记',tags:'生活,个人空间',status:'published',publishAt:new Date(Date.now()-86400000).toISOString(),featured:true},{title:'一个可以搬走的个人网站',slug:'portable-personal-site',excerpt:'让代码、内容与数据都有自己的位置，迁移不再意味着重新开始。',content:'# 一个可以搬走的个人网站\n\n这是技术文章示例。\n\n## 清晰的边界\n\n代码用于描述行为，数据库用于保存记录，图片放在独立目录。\n\n```javascript\nconst daily = { focus: true, joy: true };\nconsole.log(daily);\n```\n\n## 保留自己的选择\n\n工具会变化，记录值得留下。定期备份，让下一次迁移更从容。',category:'技术笔记',tags:'开发,自托管',status:'published',publishAt:new Date(Date.now()-2*86400000).toISOString(),featured:false},{title:'故事停下之后，还有后日谈',slug:'after-the-story',excerpt:'通关不是终点。那些留在记忆里的角色、音乐与片段，仍然参与着我们的日常。',content:'# 故事之后\n\n这是作品随笔示例，你可以换成自己的体验。\n\n## 为什么喜欢日常回\n\n没有紧迫的目标，只有人物之间慢慢生长的默契。\n\n## 留下回声\n\n在收藏里记一句感想，给这一段旅途好好收尾。',category:'作品随笔',tags:'Galgame,故事',status:'published',publishAt:new Date(Date.now()-3*86400000).toISOString(),featured:false}]);return records;
